    private app.space.notes.domain.NoteImage fixtureImage(String name,int color)throws Exception{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(32,24,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(color);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();assertTrue(bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes));bitmap.recycle();return new app.space.notes.domain.NoteImage(UUID.randomUUID().toString(),name,"image/png",32,24,java.util.Base64.getEncoder().encodeToString(bytes.toByteArray()));}
    @Test public void mixedContentPropertiesComeBeforeWritingAndRemovalKeepsOtherItems()throws Exception{
        long now=System.currentTimeMillis();Note seed=note("Site visit").properties(0,Arrays.asList("Work","Site"),now).reminder(now+86400000,now).images(Arrays.asList(fixtureImage("Image",android.graphics.Color.BLUE),fixtureImage("Drawing",android.graphics.Color.YELLOW)),now).diagram(app.space.notes.domain.Diagram.empty().put(new app.space.notes.domain.Diagram.Node("shape","process","Review",100,100,200,100,0)),now);start(Arrays.asList(seed));main(()->controller.openNote(seed.id));await(()->input("Write your note…")!=null);laidOut();main(()->{View reminder=UiActions.named(controller.view(),"Edit reminder");assertNotNull(reminder);assertTrue(((TextView)reminder).getText().toString().contains("\n"));if(android.os.Build.VERSION.SDK_INT>=30)assertEquals(((TextView)reminder).getText().toString(),reminder.getStateDescription().toString());assertTrue(((View)reminder.getParent()).getBottom()<=input("Write your note…").getTop());assertTrue(text(String.join("  ·  ",seed.labels)).getBottom()<=input("Write your note…").getTop());assertNotNull(UiActions.named(controller.view(),"Image actions"));assertNotNull(UiActions.named(controller.view(),"Drawing actions"));assertNotNull(UiActions.named(controller.view(),"Edit drawing"));});screenshot("mixed-note-header");tap("Image actions");tap("Remove image");screenshot("remove-image-confirmation");tap("Cancel");assertEquals(2,new NotesRepository(context).load().get(0).images.size());tap("Clear reminder");saved();assertEquals(0,new NotesRepository(context).load().get(0).reminderAt);
    }

    @Test public void drawingBrushAndHistoryControlsExposeActualState()throws Exception{
        start(Collections.emptyList());tap("New text note");tap("Add to note");tap("Drawing");String name="Drawing canvas. Draw with a finger. Undo and redo controls are below.";await(()->{View p=UiActions.named(controller.view(),name);return p!=null && p.isEnabled() && p.getWidth()>0;});main(()->{assertFalse(UiActions.named(controller.view(),"Undo").isEnabled());assertFalse(UiActions.named(controller.view(),"Redo").isEnabled());});tap("Ink colour");main(()->assertTrue(text("Black").isSelected()));tap("Blue");tap("Ink colour");main(()->assertTrue(text("Blue").isSelected()));tap("Cancel");main(()->{View p=UiActions.named(controller.view(),name);long now=android.os.SystemClock.uptimeMillis();for(int i=0;i<3;i++){MotionEvent e=MotionEvent.obtain(now,now+i*20,new int[]{0,2,1}[i],p.getWidth()*(i==0?.2f:i==1?.5f:.8f),p.getHeight()*.5f,0);assertTrue(p.dispatchTouchEvent(e));e.recycle();}assertTrue(UiActions.named(controller.view(),"Undo").isEnabled());});tap("Undo");main(()->{assertFalse(UiActions.named(controller.view(),"Undo").isEnabled());assertTrue(UiActions.named(controller.view(),"Redo").isEnabled());});tap("Redo");main(()->{assertTrue(UiActions.named(controller.view(),"Undo").isEnabled());assertFalse(UiActions.named(controller.view(),"Redo").isEnabled());});tap("Back");await(()->input("Write your note…")!=null);saved();assertEquals(0,new NotesRepository(context).load().get(0).images.size());
    }
    private void remove(File f){File[] files=f.listFiles();if(files!=null)for(File child:files)remove(child);f.delete();}
    @After public void cleanup(){if(controller!=null)main(controller::close);if(activity!=null){for(String name:new String[]{"mynotes-storage-v1","mynotes-ui"})activity.deleteSharedPreferences(fixture.getName()+"-"+name);main(activity::finish);}if(fixture!=null)remove(fixture);}
